svg.script:

window.addEventListener('DOMContentLoaded', () => {
  const ball = document.getElementById('ball');
  const playerPaddle = document.getElementById('playerPaddle');
  const aiPaddle = document.getElementById('aiPaddle');
  const playerScoreEl = document.getElementById('playerScore');
  const aiScoreEl = document.getElementById('aiScore');

  let ballX = 400, ballY = 250;
  let ballVX = 0, ballVY = 0;
  let playerY = 210, aiY = 210;
  let playerScore = 0, aiScore = 0;
  let gameStarted = false;

  const paddleHeight = 80;
  const paddleWidth = 16;
  const boardHeight = 500;
  const boardWidth = 800;

  let keys = {};
  window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (e.key === ' ' && !gameStarted) {
      startBall();
    }
    if (e.key === '`') {
      window.location.href = "https://www.google.com";
    }
  });
  window.addEventListener('keyup', (e) => { keys[e.key] = false; });

  function startBall() {
    gameStarted = true;
    ballX = 400;
    ballY = 250;
    const angle = (Math.random() * 0.6 - 0.3);
    const speed = 5;
    const direction = Math.random() > 0.5 ? 1 : -1;
    ballVX = direction * speed * Math.cos(angle);
    ballVY = speed * Math.sin(angle);
  }

  function update() {
    if (gameStarted) {
      ballX += ballVX;
      ballY += ballVY;

      if (ballY <= 10 || ballY >= boardHeight - 10) {
        ballVY = -ballVY;
      }

      if ((keys['w'] || keys['W'] || keys['ArrowUp']) && playerY > 10) {
        playerY -= 7;
      }
      if ((keys['s'] || keys['S'] || keys['ArrowDown']) && playerY < boardHeight - paddleHeight - 10) {
        playerY += 7;
      }

      if (aiY + paddleHeight / 2 < ballY - 15) aiY += 4.5;
      if (aiY + paddleHeight / 2 > ballY + 15) aiY -= 4.5;
      aiY = Math.max(10, Math.min(boardHeight - paddleHeight - 10, aiY));

      // Player collision
      if (ballX <= 30 + paddleWidth && ballY >= playerY && ballY <= playerY + paddleHeight) {
        ballVX = -ballVX * 1.05;
        let deltaY = ballY - (playerY + paddleHeight / 2);
        ballVY = deltaY * 0.15;
      }
      // AI collision
      if (ballX >= 754 - 10 && ballY >= aiY && ballY <= aiY + paddleHeight) {
        ballVX = -ballVX * 1.05;
        let deltaY = ballY - (aiY + paddleHeight / 2);
        ballVY = deltaY * 0.15;
      }

      if (ballX < 0) {
        aiScore++;
        aiScoreEl.textContent = aiScore;
        gameStarted = false;
        ballVX = 0; ballVY = 0;
        ballX = 400; ballY = 250;
      } else if (ballX > boardWidth) {
        playerScore++;
        playerScoreEl.textContent = playerScore;
        gameStarted = false;
        ballVX = 0; ballVY = 0;
        ballX = 400; ballY = 250;
      }
    }

    playerPaddle.setAttribute('y', playerY);
    aiPaddle.setAttribute('y', aiY);
    ball.setAttribute('cx', ballX);
    ball.setAttribute('cy', ballY);

    requestAnimationFrame(update);
  }

  requestAnimationFrame(update);
});
